<template><div class="space-y-6"><CPageHeader title="Solicitudes de huéspedes" description="Revisa cambios y cancelaciones. Solo una aprobación modifica la reserva." /><p v-if="error" role="alert" class="operation-error">{{ error }}</p><CCard><div class="operation-form"><label>Estado<select v-model="status" @change="page=1;load()"><option value="pending">Pendientes</option><option value="approved">Aprobadas</option><option value="rejected">Rechazadas</option></select></label><CButton variant="secondary" :loading="busy" @click="load">Actualizar</CButton></div></CCard><CCard v-for="r in requests" :key="r.id" class="space-y-4"><div class="operation-heading"><h2>{{ r.client_name }} · {{ r.kind==='dates'?'Cambio de fechas':'Cancelación' }}</h2><NuxtLink :to="`/reservations/${r.reservation_id}`" class="underline">Reserva #{{ r.reservation_id }}</NuxtLink></div><p v-if="r.check_in">Fechas solicitadas: {{ r.check_in }} → {{ r.check_out }}</p><p>{{ r.reason }}</p><p v-if="r.response">Respuesta: {{ r.response }}</p><form v-if="r.status==='pending' && manager" class="space-y-4" @submit.prevent="review(r)"><div class="operation-form"><label>Decisión<select v-model="decisions[r.id]"><option value="approved">Aprobar</option><option value="rejected">Rechazar</option></select></label><label v-if="r.kind==='dates' && decisions[r.id]==='approved'">Total acordado para la nueva estancia<input v-model.number="totals[r.id]" type="number" min="0" max="99999999.99" step="0.01" required></label></div><label class="block text-sm">Respuesta al huésped<textarea v-model="responses[r.id]" class="operation-filter block w-full mt-2" rows="3" minlength="5" maxlength="1000" required placeholder="Explica las condiciones y la tarifa acordada." /></label><p v-if="r.kind==='cancel'" class="text-sm">La aprobación cancela la reserva. Gestiona los importes cobrados desde Pagos en línea o desde el pago original.</p><CButton type="submit" :loading="busy">Guardar decisión y notificar</CButton></form></CCard><CEmptyState v-if="!requests.length && !busy" title="No hay solicitudes" description="Las solicitudes de los huéspedes aparecerán aquí." /><div class="operation-pager"><CButton variant="secondary" :disabled="page===1||busy" @click="page--;load()">Anterior</CButton><span>Página {{ page }}</span><CButton variant="secondary" :disabled="requests.length<20||busy" @click="page++;load()">Siguiente</CButton></div></div></template>
<script setup lang="ts">
import type {ReservationRequest} from '~/types/guestServices'
definePageMeta({middleware:'auth'})
const {get,post,run,error,busy}=useOperations(),auth=useAuthStore(),manager=computed(()=>auth.isAdmin||auth.isManager),status=ref('pending'),page=ref(1),requests=ref<ReservationRequest[]>([]),responses=reactive<Record<number,string>>({}),decisions=reactive<Record<number,string>>({}),totals=reactive<Record<number,number>>({})
const fetchRequests=async()=>{requests.value=(await get<ReservationRequest[]>('reservation-requests',{status:status.value,page:page.value})).data||[];for(const r of requests.value){decisions[r.id]??='approved';totals[r.id]??=Number(r.total_price)}}
const load=()=>run(fetchRequests)
const review=(r:ReservationRequest)=>run(async()=>{await post(`reservation-requests/${r.id}/review`,{decision:decisions[r.id],response:responses[r.id],...(r.kind==='dates'&&decisions[r.id]==='approved'?{total_price:totals[r.id]}:{})});await fetchRequests()})
onMounted(load)
</script>
